  storage: { get(key: string): any; set(key: string, value: any): void; remove(key: string): void };
  now(): number;
  requestFrame(callback: (time: number) => void): any;
  cancelFrame(id: any): void;
  toast?(message: string): void;
  confirm?(message: string): Promise<boolean>;
  importJson?(): Promise<string | null>;
  exportJson?(text: string): Promise<void>;
  exportImage?(canvas: any): Promise<void>;
}
type Hit = Rect & { id: string; action: () => void; disabled?: boolean };
type Paste = { ticket: any; sticker: any; start: number; from: Point; to: Point };
const ease = (p: number) => { p = Math.max(0, Math.min(1, p)); return p * p * (3 - 2 * p); };
const lerp = (a: number, b: number, p: number) => a + (b - a) * p;
const contains = (r: Rect, x: number, y: number) => x >= r.x && y >= r.y && x <= r.x + r.width && y <= r.y + r.height;

/** Canvas renderer shared by the real WeChat entry and a separate diagnostic host.
 * It never reads DOM, window, browser storage, CSS, or the device's filesystem.
 * Native App uses the Sprite-based Cocos adapter with this same layout/session.
 */
export class CanvasGame {
  readonly canvas: any;
  readonly platform: GamePlatform;
  layout: any;
  private sourceLayout: any;
  session: GameSession;
  private context: any;
  private images = new Map<string, any>();
  private loading = new Map<string, Promise<any>>();
  private alphas = new Map<string, { pixels: Uint8ClampedArray; width: number; height: number }>();
  private backs = new Map<string, any>();
  private silhouettes = new Map<string, any>();
  private clippedViews = new Map<string, ClippedView>();
  private clippedMasks = new Map<string, Uint8Array>();
  private width = 390;
  private height = 844;
  private ratio = 1;
  private safe = { left: 0, top: 0, right: 390, bottom: 844 };
  private sceneRect: Rect = { x: 16, y: 126, width: 358, height: 468 };
  private boardSpace: Rect = { x: 16, y: 126, width: 358, height: 468 };
  private trayRect: Rect = { x: 16, y: 610, width: 358, height: 180 };
  private sideTray = false;
  private camera: Camera = { x: 270, y: 210, scale: 0.6 };
  private hits: Hit[] = [];
  private dirty = true;
  private running = false;
  private frame: any = null;
  private pointer: { id: number; start: Point; at: Point; moved: boolean; button?: Hit } | null = null;
  private heldAt: Point | null = null;
  private paste: Paste | null = null;
  private burst: { start: number; at: Point; final: boolean } | null = null;
  private tour: { start: number; from: Camera; to: Camera; overview: Camera;
    fromRect: Rect; overviewRect: Rect; toRect: Rect } | null = null;
  private overview = false;
  private page = 0;
  private editor = false;
  private draft: any = null;
  private editId: string | null = null;
  private editUndo: any[] = [];
  private editRedo: any[] = [];
  private editDragStart: Point | null = null;
  private editDragRecorded = false;
  private recoveredDraft: any = null;
  private acceptedEditedLayout = false;
  private loaded = false;
  private status = '准备温泉庭院素材…';
  private unsubscribe: (() => void) | null = null;

  constructor(options: { canvas: any; layout: any; platform: GamePlatform }) {
    this.canvas = options.canvas;
    this.context = this.canvas.getContext('2d');
    this.platform = options.platform;
    this.layout = JSON.parse(JSON.stringify(options.layout));
    this.sourceLayout = JSON.parse(JSON.stringify(options.layout));
    const errors = validateRenderableLayout(this.layout);
    if (errors.length) throw new Error(`排布数据不完整：${errors[0]}`);
    this.session = new GameSession(this.layout);
  }

  async start(): Promise<void> {
    const edited = this.platform.storage.get(this.layoutKey());
    if (edited && validateRenderableLayout(edited, this.sourceLayout).length === 0) {
      const upgrade = upgradeEditedAssemblyLayout(this.sourceLayout, edited);
      this.layout = upgrade?.layout ?? edited;
      this.acceptedEditedLayout = true;
      if (upgrade) {
        const archiveKey = `${this.layoutKey()}:before-assembly-policy:${upgrade.previousLayoutRevision}`;
        if (!this.platform.storage.get(archiveKey)) this.platform.storage.set(archiveKey, upgrade.previousLayout);
        const historical = this.platform.storage.get(this.saveKey(upgrade.previousLayoutRevision));
        const migrated = historical && migrateEditedAssemblyProgress(upgrade, historical);
        if (migrated) this.platform.storage.set(this.saveKey(), migrated);
        else if (historical) this.platform.toast?.('排布流程已更新，旧进度记录已保留。');
        this.platform.storage.set(this.layoutKey(), this.layout);
      }
    }
    const draft = this.platform.storage.get(`${this.layoutKey()}:draft`);
    if (draft && draft.layoutRevision === this.layout.layoutRevision && validateRenderableLayout(draft, this.sourceLayout).length === 0) this.recoveredDraft = draft;
    this.bindSession();
    const save = this.platform.storage.get(this.saveKey());
    if (save) {
      const result = this.session.restore(save);
      if (!result.ok) this.platform.toast?.('排布版本已更新，已保留旧记录并从本关开始。');
    } else {
      for (const revision of compatibleProgressRevisions(this.sourceLayout, this.layout, this.acceptedEditedLayout)) {
        const legacy = this.platform.storage.get(this.saveKey(revision));
        const migrated = migrateCompatibleProgress(this.sourceLayout, this.layout, legacy, this.acceptedEditedLayout);
        if (migrated && this.session.restore(migrated).ok) { this.persist(); break; }
      }
    }
    this.resize(this.width, this.height, this.ratio, this.safe);
    this.running = true;
    this.tick();
    await Promise.all([this.image(this.layout.scene.baseAssetKey), ...(this.layout.scene.basePatches || []).map((p: any) => this.image(p.assetKey)), ...this.layout.fixedLayers.map((f: any) => this.image(f.assetKey))]);
