    this.loaded = true;
    this.status = '拿起贴纸，寻找它在温泉庭院里的位置';
    this.camera = this.cameraForCurrent();
    if (this.session.getSnapshot().phase === 'transitioning') this.startTour();
    this.dirty = true;
  }

  private bindSession(): void {
    this.unsubscribe?.();
    this.session = new GameSession(this.layout);
    this.unsubscribe = this.session.subscribe((snapshot, event) => {
      if (event.type !== 'selected' && event.type !== 'selection-cancelled') this.persist();
      if (event.type === 'transition-finished' || event.type === 'undo') {
        this.page = 0;
        this.loadCurrentAndNext().catch(() => this.platform.toast?.('素材读取失败，请重试。'));
      }
      if (!this.editor && !this.overview && !this.paste && !this.tour
          && ['selected', 'transition-finished', 'undo'].includes(event.type)) this.camera = this.cameraForCurrent();
      this.dirty = true;
    });
  }

  resize(width: number, height: number, ratio = 1, safeArea?: any): void {
    this.width = Math.max(1, width); this.height = Math.max(1, height); this.ratio = Math.max(1, ratio);
    this.safe = safeArea || { left: 0, top: 0, right: width, bottom: height };
    this.canvas.width = Math.round(this.width * this.ratio); this.canvas.height = Math.round(this.height * this.ratio);
    const top = Math.max(12, this.safe.top || 0);
    const bottom = Math.max(10, this.height - (this.safe.bottom || this.height));
    const contentWidth = Math.min(1180, this.width - 32);
    this.sideTray = !this.editor && this.width >= 700 && this.width > this.height * 1.1;
    if (this.sideTray) {
