    return alpha.pixels[(py * alpha.width + px) * 4 + 3] > 18;
  }
  private paperBack(s: any): any {
    if (!this.backs.has(s.assetKey)) this.backs.set(s.assetKey, makePaperBack(this.images.get(s.assetKey), (w: number, h: number) => this.platform.createCanvas(w, h)));
    return this.backs.get(s.assetKey);
  }
  private silhouette(s: any): any {
    if (this.silhouettes.has(s.assetKey)) return this.silhouettes.get(s.assetKey);
    const image = this.images.get(s.assetKey), canvas = this.platform.createCanvas(image.width, image.height), c = canvas.getContext('2d');
    c.drawImage(image, 0, 0); c.globalCompositeOperation = 'source-in'; c.fillStyle = '#513b34'; c.fillRect(0, 0, canvas.width, canvas.height);
    this.silhouettes.set(s.assetKey, canvas); return canvas;
  }

  pointerDown(x: number, y: number, id = 0): void {
    if (!this.loaded || this.pointer || this.paste || this.tour || this.burst) return;
    const button = this.hits.slice().reverse().find(h => contains(h, x, y));
    if (button?.disabled) return;
    this.pointer = { id, start: { x, y }, at: { x, y }, moved: false, button };
    if (button?.id.startsWith('sticker:')) {
      const sid = button.id.slice(8); button.action();
      if (!this.editor && this.session.getSnapshot().selectedStickerId) this.heldAt = { x, y: y - 62 };
      return;
    }
    if (this.editor && contains(this.sceneRect, x, y)) {
      const found = this.editorHit({ x, y });
      this.editDragRecorded = false;
      if (found) { this.editId = found.stickerId; this.editDragStart = { ...found.position }; }
      this.dirty = true;
    }
  }
  pointerMove(x: number, y: number, id = 0): void {
    if (!this.pointer || this.pointer.id !== id) return;
    this.pointer.at = { x, y };
    if (Math.hypot(x - this.pointer.start.x, y - this.pointer.start.y) > 7) this.pointer.moved = true;
    if (this.editor && this.editId && this.editDragStart && !this.pointer.button && this.pointer.moved) {
      if (!this.editDragRecorded) { this.pushEditUndo(); this.editDragRecorded = true; }
      const delta = { x: (x - this.pointer.start.x) / this.camera.scale, y: (y - this.pointer.start.y) / this.camera.scale };
      this.draft = patchStickerDraft(this.draft, this.editId, { position: { x: this.editDragStart.x + delta.x, y: this.editDragStart.y + delta.y } });
    } else if (this.session.getSnapshot().selectedStickerId && this.pointer.moved) this.heldAt = { x, y: y - 62 };
    this.dirty = true;
  }
  pointerUp(x: number, y: number, id = 0): void {
    if (!this.pointer || this.pointer.id !== id) return;
    const pointer = this.pointer; this.pointer = null; this.editDragStart = null;
    if (this.editor) {
      if (pointer.button && !pointer.button.id.startsWith('sticker:') && !pointer.moved && contains(pointer.button, x, y)) pointer.button.action();
      this.dirty = true; return;
    }
    if (pointer.button && !pointer.button.id.startsWith('sticker:')) {
      if (!pointer.moved && contains(pointer.button, x, y)) pointer.button.action();
      this.dirty = true; return;
    }
    const sid = this.session.getSnapshot().selectedStickerId;
    if (!sid) return;
    const dragged = pointer.moved || Math.hypot(x - pointer.start.x, y - pointer.start.y) > 7;
    if (pointer.button?.id.startsWith('sticker:') && !dragged) { this.dirty = true; return; }
    const s = this.sticker(sid);
    // Use the release event, even when the platform coalesced the last move.
    // Both the fingertip and the visibly raised paper can align to its target.
    const finger = { x, y }, held = dragged ? { x, y: y - 62 } : finger;
    if (this.dropAtTarget(s, finger) || (dragged && this.dropAtTarget(s, held))) this.place(s, held);
    else {
      this.heldAt = held;
      this.status = '贴纸仍在手中，请对准阴影';
      this.dirty = true;
    }
  }
  pointerCancel(id?: number): void {
    if (id !== undefined && this.pointer && this.pointer.id !== id) return;
    this.pointer = null; this.editDragStart = null; this.heldAt = null;
    if (!this.editor) this.session.cancelSelection();
    this.dirty = true;
  }

  private place(s: any, from: Point): void {
    const ticket = this.session.beginPlacement(s.stickerId); if (!ticket) return;
    this.overview = false;
    this.paste = { ticket, sticker: s, start: this.platform.now(), from, to: this.screen(this.center(s)) };
    this.heldAt = null; this.status = '从左侧轻轻压平…'; this.dirty = true;
  }
  private startTour(): void {
    const current = this.session.getSnapshot().activeBlockId;
    const blocks = this.layout.geoBlocks.slice().sort((a: any, b: any) => a.blockOrder - b.blockOrder);
