    this.sceneRect = fromRect;
    this.tour = { start: this.platform.now(), from, fromRect, overview, overviewRect, to, toRect };
    this.status = '这一角完成了，看看整座温泉庭院'; this.dirty = true;
  }
  private tick = (): void => {
    if (!this.running) return;
    const now = this.platform.now();
    if (this.paste && now - this.paste.start >= 1550) {
      const paste = this.paste; this.paste = null;
      if (this.session.commitPlacement(paste.ticket)) {
        const state = this.session.getSnapshot();
        this.burst = { start: now, at: paste.to, final: state.phase === 'transitioning' || state.phase === 'completed' };
        this.page = 0; this.status = state.phase === 'completed' ? '月下温泉，已经完整呈现' : '贴好了，给这一角一点星光';
      }
      this.dirty = true;
    }
    if (this.burst && now - this.burst.start >= 1350) {
      this.burst = null;
      if (this.session.getSnapshot().phase === 'transitioning') this.startTour();
      else {
        this.status = this.session.getSnapshot().phase === 'completed' ? '整幅温泉庭院已经完成，可以保存画面' : '拿起下一张，继续还原这一角';
        this.camera = this.cameraForCurrent(); this.dirty = true;
      }
    }
    if (this.tour) {
      const t = now - this.tour.start; let from: Camera, to: Camera, fromRect: Rect, toRect: Rect, p: number;
      if (t < 700) { from = this.tour.from; to = this.tour.overview; fromRect = this.tour.fromRect; toRect = this.tour.overviewRect; p = ease(t / 700); }
      else if (t < 1150) { from = to = this.tour.overview; fromRect = toRect = this.tour.overviewRect; p = 1; }
      else { from = this.tour.overview; to = this.tour.to; fromRect = this.tour.overviewRect; toRect = this.tour.toRect; p = ease((t - 1150) / 800); }
      this.camera = { x: lerp(from.x, to.x, p), y: lerp(from.y, to.y, p), scale: lerp(from.scale, to.scale, p) };
      this.sceneRect = { x: lerp(fromRect.x, toRect.x, p), y: lerp(fromRect.y, toRect.y, p),
        width: lerp(fromRect.width, toRect.width, p), height: lerp(fromRect.height, toRect.height, p) };
      if (t >= 1950) { this.tour = null; this.session.finishTransition(); this.overview = this.session.getSnapshot().phase === 'completed'; this.camera = this.cameraForCurrent(); this.status = this.overview ? '整幅温泉庭院已经完成，可以保存画面' : '新的角落，新的故事'; }
    }
    if (this.dirty || this.paste || this.burst || this.tour) { this.render(now); this.dirty = false; }
    this.frame = this.platform.requestFrame(this.tick);
  };

  /** Draws immutable base and effective object parts in one global paint order. */
