        } else c.drawImage(image, dx, dy, f.sourceSize.width, f.sourceSize.height);
    c.lineTo(r.x + k, r.y + r.height); c.quadraticCurveTo(r.x, r.y + r.height, r.x, r.y + r.height - k); c.lineTo(r.x, r.y + k); c.quadraticCurveTo(r.x, r.y, r.x + k, r.y); c.closePath();
  }
