    c.save(); c.globalAlpha = disabled ? .35 : 1; this.rounded(c, r, 9); c.fillStyle = active ? '#7f34

  this.camera = this.cameraForCurrent();
  if (this.session.getSnapshot().phase === 'transitioning') this.startTour();
  this.dirty = true;
}

