    try {
      const stored = sys.localStorage.getItem(activeKey);
      if (!stored) return;
      const parsed = JSON.parse(stored) as GameLayout;
      if (validateRenderableLayout(parsed, this.sourceLayout).length) return;
      const upgrade = upgradeEditedAssemblyLayout(this.sourceLayout, parsed);
