      try { if (historicalText) historical = JSON.parse(historicalText); } catch { /* Keep its exact old bytes. */ }
      const migrated = historicalText ? migrateEditedAssemblyProgress(upgrade, historical) : null;
      if (historicalText && !migrated) this.startupNotice = '排布流程已更新，旧进度记录已保留。';
      try {
        const archiveKey = `${activeKey}:before-assembly-policy:${upgrade.previousLayoutRevision}`;
        const archived = sys.localStorage.getItem(archiveKey);
        if (archived === null || archived === undefined) sys.localStorage.setItem(archiveKey, stored);
        if (migrated) sys.localStorage.setItem(this.saveKey(), JSON.stringify(migrated));
        sys.localStorage.setItem(activeKey, JSON.stringify(this.layout));
      } catch { this.startupNotice = '排布流程已更新，本机空间不足；旧记录仍保留。'; }
    } catch { /* Corrupt layouts cannot replace the current source artwork. */ }
  }
  private isKnownDraft(value: unknown): value is GameLayout {
    try { return validateOnsenDraft(value, this.sourceLayout).length === 0; } catch { return false; }
  }
  private draftKey(): string { return `onsen-layout-draft:${this.layout.sceneId}`; }
  private persist(): void { try { sys.localStorage.setItem(this.saveKey(), JSON.stringify(this.session.exportSave())); } catch { if (this.hint) this.hint.string = '本机空间不足，进度暂未保存'; } }
  private restoreProgress(): void {
    try {
      const saved = sys.localStorage.getItem(this.saveKey());
      if (saved) { this.session.restore(JSON.parse(saved)); return; }
      for (const revision of compatibleProgressRevisions(this.sourceLayout, this.layout, this.acceptedEditedLayout)) {
        const historical = sys.localStorage.getItem(this.saveKey(revision));
        if (!historical) continue;
        let migrated = null;
        try { migrated = migrateCompatibleProgress(this.sourceLayout, this.layout, JSON.parse(historical), this.acceptedEditedLayout); }
        catch { continue; }
        if (migrated && this.session.restore(migrated).ok) { this.persist(); break; }
      }
    }
    catch { /* Corrupt save cannot modify a new session. */ }
  }
  private onHide(): void {
    this.suspended = true; this.gesture = null; this.clearGhost(); this.clearCelebrations();
    if (this.booted) { if (!this.busy) this.session.cancelSelection(); this.persist(); }
  }
  private onShow(): void { this.suspended = false; if (this.booted && !this.busy) this.refresh(); }

  private resourcePath(file: string): string {
    const path = file.replace(/^resources\//, '').replace(/\.png$/i, '');
    if (!path || path.startsWith('/') || path.split('/').includes('..')) throw new Error('非法本地资源路径');
    return `${this.resourcePrefix}/${path}/spriteFrame`;
  }
  private loadFrame(file: string): Promise<SpriteFrame> {
    const cached = this.frames.get(file); if (cached) return Promise.resolve(cached);
    return new Promise((resolve, reject) => resources.load(this.resourcePath(file), SpriteFrame, (error, frame) => {
      if (error) { reject(error); return; }
      if (!this.alive || !isValid(this.node)) { reject(new Error('组件已销毁')); return; }
      frame.packable = false; frame.addRef(); this.loadedAssets.push(frame); this.frames.set(file, frame); resolve(frame);
    }));
  }
  private loadJson(path: string): Promise<JsonAsset> {
    return new Promise((resolve, reject) => resources.load(path, JsonAsset, (error, asset) => {
      if (error) { reject(error); return; }
      if (!this.alive || !isValid(this.node)) { reject(new Error('组件已销毁')); return; }
      asset.addRef(); this.loadedAssets.push(asset); resolve(asset);
    }));
  }
}

